import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, mkdir, writeFile, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const { createCanvas, loadImage } = require('@napi-rs/canvas');
import { makeVertical } from '../../../../scripts/video/vertical-highlight';
import { buildClips } from '../../../../scripts/video/project';
import { wavHeader } from '../../../../scripts/video/audio';
import { isPlayerSpeech } from '../../../../scripts/video/vertical-scene';
const hash = (s: Buffer) => createHash('sha256').update(s).digest('hex');
test('reviewed portrait is bound to original samples and nonuniform word times', { timeout: 120000 }, async () => {
  const root = await mkdtemp(join(tmpdir(), 'vertical-test-'));
  try {
    const src = join(root, 'source'), out = join(root, 'new-output'); await mkdir(src); await mkdir(join(src, 'audio'));
    const entry = { sourceSeq: 1, type: 'speech', speaker: 'Ethan', voiceKey: 'seat-1', seat: 1, text: 'Hello world.', visibility: 'public', data: {} };
    const script = { roomId: 'synthetic', perspective: 'god', status: 'ended', locale: 'en', presetName: 'test', cast: [{ seat: 1, name: 'Ethan', role: 'villager', roleName: 'Villager', factionName: 'Good', voiceKey: 'seat-1' }], events: [], chapters: [{ day: 1, phase: 'day', title: 'Day 1', entries: [entry] }], result: {} };
    const source = Buffer.from(JSON.stringify(script));
    const clip = buildClips(script)[0];
    assert(isPlayerSpeech(clip));
    assert(!isPlayerSpeech({ ...clip, seat: undefined, voiceKey: 'judge' }));
    assert(!isPlayerSpeech({ ...clip, type: 'vote.result' }));
    assert(!isPlayerSpeech({ ...clip, data: { presentationOnly: true } }));
    await writeFile(join(src, 'source.json'), source); await writeFile(join(src, 'script.json'), source);
    await writeFile(join(src, 'voices.json'), JSON.stringify({model: 'synthetic', profiles: {'seat-1': {voice: 'test-voice', instruction: '', rate: 1}}}));
    await writeFile(join(src, 'clips.json'), JSON.stringify([clip])); await writeFile(join(src, 'avatar-theme.json'), '{"theme":"urban"}');
    const samples = 24000, pcm = Buffer.alloc(samples * 2);
    for (let i = 0; i < samples; i++) pcm.writeInt16LE(Math.round(4000 * Math.sin(i * .087)), i * 2);
    const wav = Buffer.concat([wavHeader(samples, 24000), pcm]);
    await writeFile(join(src, 'audio', `${clip.id}.wav`), wav);
    await writeFile(join(src, 'audio', `${clip.id}.wav.json`), JSON.stringify({ model: 'synthetic', voice: 'test-voice', text: entry.text, bytes: wav.length, sentences: [{ index: 0, text: entry.text, words: [{ text: 'Hello', begin_time: 100, end_time: 340 }, { text: ' world.', begin_time: 410, end_time: 820 }] }] }));
    const selection = { roomId: 'synthetic', sourceSha256: hash(source), reviewed: true, theme: 'urban', clips: [{ id: clip.id, quote: entry.text, audioSha256: hash(wav), factReview: 'Synthetic source checked', audioReview: 'Synthetic samples checked', excerptNote: 'Whole clip' }] };
    const plan = join(root, 'selection.json'); const save = async (x: unknown) => writeFile(plan, JSON.stringify(x));
    await save({ ...selection, reviewed: false }); await assert.rejects(makeVertical(src, plan, out, 'cpu'), /reviewed/);
    await save({ ...selection, roomId: 'other' }); await assert.rejects(makeVertical(src, plan, out, 'cpu'), /room or source hash/);
    await save({ ...selection, sourceSha256: 'wrong' }); await assert.rejects(makeVertical(src, plan, out, 'cpu'), /room or source hash/);
    await save({ ...selection, clips: [{ ...selection.clips[0], id: 'unknown' }] }); await assert.rejects(makeVertical(src, plan, out, 'cpu'), /Unknown/);
    for (const [wordStart, wordEnd] of [[-1, 1], [1, 1], [0, 3], [.5, 1], [1, .5]]) {
      await save({ ...selection, clips: [{ ...selection.clips[0], wordStart, wordEnd }] });
      await assert.rejects(makeVertical(src, plan, out, 'cpu'), /Invalid word range/);
    }
    await save({ ...selection, clips: [{ ...selection.clips[0], wordStart: 1, wordEnd: 2, quote: 'wrong' }] });
    await assert.rejects(makeVertical(src, plan, out, 'cpu'), /Quote differs from word range/);
    await save({ ...selection, clips: [{ ...selection.clips[0], start: 0.1 }] }); await assert.rejects(makeVertical(src, plan, out, 'cpu'), /whole clips/);
    for (const story of [{ headline: '' }, { headline: 'x'.repeat(81) }, { headline: 'Scene', focusSeats: [99] }, { headline: 'Scene', focusSeats: [1, 1] }]) {
      await save({ ...selection, clips: [{ ...selection.clips[0], story }] }); await assert.rejects(makeVertical(src, plan, out, 'cpu'), /story/);
    }
    await save({ ...selection, clips: [selection.clips[0], selection.clips[0]] }); await assert.rejects(makeVertical(src, plan, out, 'cpu'), /duplicate/);
    await save({ ...selection, clips: [{ ...selection.clips[0], audioSha256: 'wrong' }] }); await assert.rejects(makeVertical(src, plan, out, 'cpu'), /Audio hash/);
    await save({ ...selection, clips: [{ ...selection.clips[0], quote: 'wrong' }] }); await assert.rejects(makeVertical(src, plan, out, 'cpu'), /Quote/);
    await writeFile(join(src, 'voices.json'), JSON.stringify({ model: 'wrong', profiles: { 'seat-1': { voice: 'test-voice', instruction: '', rate: 1 } } }));
    await save(selection); await assert.rejects(makeVertical(src, plan, out, 'cpu'), /Audio model/);
    await writeFile(join(src, 'voices.json'), JSON.stringify({ model: 'synthetic', profiles: { 'seat-1': { voice: 'wrong', instruction: '', rate: 1 } } }));
    await assert.rejects(makeVertical(src, plan, out, 'cpu'), /Audio voice/);
    await writeFile(join(src, 'voices.json'), JSON.stringify({ model: 'synthetic', profiles: { 'seat-1': { voice: 'test-voice', instruction: '', rate: 1 } } }));
    await writeFile(join(src, 'script.json'), JSON.stringify({ ...script, events: [{ sourceSeq: 10 }] }));
    await assert.rejects(makeVertical(src, plan, out, 'cpu'), /changes source facts/);
    await writeFile(join(src, 'script.json'), source);
    const player = Buffer.from(JSON.stringify({ ...script, perspective: 'player' })); await writeFile(join(src, 'source.json'), player);
    await save({ ...selection, sourceSha256: hash(player) }); await assert.rejects(makeVertical(src, plan, out, 'cpu'), /god/);
    await writeFile(join(src, 'source.json'), source);
    const longWav = Buffer.concat([wavHeader(samples * 121, 24000), ...Array.from({ length: 121 }, () => pcm)]);
    await writeFile(join(src, 'audio', `${clip.id}.wav`), longWav);
    await writeFile(join(src, 'audio', `${clip.id}.wav.json`), JSON.stringify({ model: 'synthetic', voice: 'test-voice', text: entry.text, bytes: longWav.length, sentences: [{ index: 0, text: entry.text, words: [{ text: 'Hello', begin_time: 100, end_time: 340 }, { text: ' world.', begin_time: 410, end_time: 820 }] }] }));
    await save({ ...selection, clips: [{ ...selection.clips[0], audioSha256: hash(longWav) }] });
    await assert.rejects(makeVertical(src, plan, out, 'cpu'), /exceeds 120 seconds/);
    await writeFile(join(src, 'audio', `${clip.id}.wav`), wav);
    await writeFile(join(src, 'audio', `${clip.id}.wav.json`), JSON.stringify({ model: 'synthetic', voice: 'test-voice', text: entry.text, bytes: wav.length, sentences: [{ index: 0, text: entry.text, words: [{ text: 'Hello', begin_time: 100, end_time: 340 }, { text: ' world.', begin_time: 410, end_time: 820 }] }] }));
    await save({ ...selection, clips: [{ ...selection.clips[0], story: { headline: 'One recorded story', detail: 'Original words and timing', focusSeats: [1] } }] }); await makeVertical(src, plan, out, 'cpu');
    const ringA = await readFile(join(out, 'rings', '000', '000000.png'));
    const ringB = await readFile(join(out, 'rings', '000', '000015.png'));
    const ringSilent = await readFile(join(out, 'rings', '000', '000035.png'));
    assert.notEqual(hash(ringA), hash(ringB), 'Rings must move between real video frames');
    const alpha = async (image: Buffer) => {
      const canvas = createCanvas(820, 820), ctx = canvas.getContext('2d'); ctx.drawImage(await loadImage(image), 0, 0);
      const pixels = ctx.getImageData(0, 0, 820, 820).data; let total = 0;
      for (let i = 3; i < pixels.length; i += 4) total += pixels[i];
      const radii = Array.from({ length: 13 }, (_, i) => {
        const angle = Math.PI + i * Math.PI / 12; let edge = 0;
        for (let r = 350; r < 409; r++) { const x = Math.round(410 + Math.cos(angle) * r), y = Math.round(410 + Math.sin(angle) * r); if (pixels[(y * 820 + x) * 4 + 3] > 40) edge = r; }
        return edge;
      }).filter(r => r > 0);
      return { total, face: pixels[(410 * 820 + 410) * 4 + 3], radii };
    };
    const active = await alpha(ringA), silent = await alpha(ringSilent);
    assert(active.total > 0 && active.face === 0, 'Wave must be visible without covering the face');
    assert(Math.max(...active.radii) - Math.min(...active.radii) > 10, 'Outer wave must deform locally instead of uniformly changing a circular radius');
    assert.equal(silent.total, 0, 'Silence must suppress the wave');
    const verification = JSON.parse(await readFile(join(out, 'output', 'verification.json'), 'utf8'));
    assert.equal(verification.frames, 36); assert.equal(verification.sampleCount, 36 * 800);
    const srt = await readFile(join(out, 'output', 'subtitles.srt'), 'utf8'); assert.match(srt, /Hello world/); assert.match(srt, /00:00:00,040/);
    await assert.rejects(makeVertical(src, plan, out, 'cpu'), /EEXIST/);
    const rangeOut = join(root, 'range-output');
    await save({ ...selection, clips: [{ ...selection.clips[0], quote: 'world.', wordStart: 1, wordEnd: 2 }] });
    await makeVertical(src, plan, rangeOut, 'cpu');
    const map = JSON.parse(await readFile(join(rangeOut, 'output', 'source-map.json'), 'utf8'));
    assert.deepEqual(map.clips[0].cut, { wordStart: 1, wordEnd: 2, firstBeginMs: 410, lastEndMs: 820, sampleStart: 8880, sampleEnd: 20640 });
    const cutMaster = await readFile(join(rangeOut, 'master.wav'));
    assert.deepEqual(cutMaster.subarray(44, 44 + 11760 * 2), pcm.subarray(8880 * 2, 20640 * 2));
    assert.match(await readFile(join(rangeOut, 'output', 'subtitles.srt'), 'utf8'), /world\./);
    const nextEntry = { ...entry, sourceSeq: 2 };
    const twoScript = { ...script, chapters: [{ ...script.chapters[0], entries: [entry, nextEntry] }] };
    const twoSource = Buffer.from(JSON.stringify(twoScript)), twoClips = buildClips(twoScript);
    await writeFile(join(src, 'source.json'), twoSource); await writeFile(join(src, 'script.json'), twoSource);
    await writeFile(join(src, 'clips.json'), JSON.stringify(twoClips));
    await writeFile(join(src, 'audio', `${twoClips[1].id}.wav`), wav);
    await writeFile(join(src, 'audio', `${twoClips[1].id}.wav.json`), await readFile(join(src, 'audio', `${clip.id}.wav.json`)));
    await save({ ...selection, sourceSha256: hash(twoSource), clips: [selection.clips[0], { ...selection.clips[0], id: twoClips[1].id }] });
    const twoOut = join(root, 'two-output'); await makeVertical(src, plan, twoOut, 'cpu');
    const twoVerification = JSON.parse(await readFile(join(twoOut, 'output', 'verification.json'), 'utf8'));
    assert.equal(twoVerification.frames, 72); assert.equal(twoVerification.sampleCount, 72 * 800);
    assert(Math.abs(Number(twoVerification.videoDuration) - Number(twoVerification.audioDuration)) <= 1 / 30 + .05);
    const twoMaster = await readFile(join(twoOut, 'master.wav'));
    assert.deepEqual(twoMaster.subarray(44, 44 + pcm.length), pcm);
    assert.deepEqual(twoMaster.subarray(44 + 36 * 800 * 2, 44 + 36 * 800 * 2 + pcm.length), pcm);
  } finally { await rm(root, { recursive: true, force: true }); }
});
